/* ---- state (copied) ---- */
const $=id=>document.getElementById(id);
const cols=META.aal.cols, cellW=META.aal.cellW, cellH=META.aal.cellH, n=META.aal.n;
const VW=window.VIEWS, ORIENT=VW.orient;
let view='axial';
let grayV={}, labV={}, grayC=null, labelCtx=null, ready=false;
let DW,DH,K;
const cv=$('cv'), ctx=cv.getContext('2d');
let tmp=document.createElement('canvas'); tmp.width=cellW; tmp.height=cellH;
let tmpCtx=tmp.getContext('2d');
let swiped=false;

/* ---- state the trainer sets from its mode / atlas buttons; fixed here because the page is quiz only ---- */
const LANG='en';
const T={en:TRAINER_TEXT};
const ATL={};
for(const key in META) ATL[key]={R:META[key].R,G:META[key].G,B:META[key].B,rep:META[key].rep,sliceMM:META[key].sliceMM};
let cur=Math.floor(n/2), opacity=0, quiz=null, marker=null, atlas='aal';

/* ---- atlas access, sprite sheets ---- */
function A(){return ATL[atlas];}
function srcXY(s){return [(s%cols)*cellW, Math.floor(s/cols)*cellH];}
function canvasOf(img){const c=document.createElement('canvas');c.width=img.width;c.height=img.height;c.getContext('2d').drawImage(img,0,0);return c;}
function ctxOf(img){const c=document.createElement('canvas');c.width=img.width;c.height=img.height;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(img,0,0);return x;}

/* ---- decode the embedded images, then build the off-screen canvases (startViewer() is called by index.html) ---- */
let grayImgV={}, labImgV={};
let _toload=0,_loaded=0;
function _mk(src){ const im=new Image(); _toload++; im.onload=()=>{ if(++_loaded===_toload) buildOffscreen(); }; im.src=src; return im; }
function startViewer(){
for(const v in ORIENT) grayImgV[v]=_mk(VW.gray[v]);
for(const key in VW.atlases){ labImgV[key]={}; for(const v in ORIENT) labImgV[key][v]=_mk(VW.atlases[key][v].label); }
}
function buildOffscreen(){
  for(const v in ORIENT) grayV[v]=canvasOf(grayImgV[v]);
  for(const key in VW.atlases){ labV[key]={}; for(const v in ORIENT) labV[key][v]=ctxOf(labImgV[key][v]); }
  K=Math.max(3, Math.round(680/cellH)); DW=cellW*K; DH=cellH*K;
  cv.width=DW; cv.height=DH;
  ready=true; applyView();
  onViewerReady();
}

/* ---- switch view / atlas sprites, orientation letters ---- */
function applyView(){
  const o=ORIENT[view];
  ATL[atlas].rep = VW.atlases[atlas][view].rep;
  ATL[atlas].sliceMM = o.sliceMM;
  grayC = grayV[view]; labelCtx = labV[atlas][view];
  if(cur>o.n-1) cur=o.n-1;
  $('slice').max=o.n-1; $('slice').value=cur;
  updateMarkers(o.mark);
  document.querySelectorAll('#viewSeg button').forEach(b=>b.classList.toggle('on',b.dataset.v===view));
  syncSlice();
  if(ready) draw();
  saveState();
}
function updateMarkers(mk){
  $('oA').textContent=mk.t; $('oP').textContent=mk.b; $('oRleft').textContent=mk.l; $('oLright').textContent=mk.r;
  $('capTop').textContent=mk.st; $('capBot').textContent=mk.sb;
}
function setView(v){
  if(v===view||!ORIENT[v])return;
  view=v;
  applyView();
  if(marker) placeQuizMarker(marker.w);
  draw();
}

/* ---- draw one slice: grey image + coloured atlas overlay ---- */
function coloredCell(s){
  const [sx,sy]=srcXY(s);
  const src=labelCtx.getImageData(sx,sy,cellW,cellH);
  const out=tmpCtx.createImageData(cellW,cellH);
  const sd=src.data, od=out.data;
  const R=A().R,G=A().G,B=A().B;
  for(let p=0;p<sd.length;p+=4){
    const idx=sd[p];
    if(idx>0&&idx<R.length){od[p]=R[idx];od[p+1]=G[idx];od[p+2]=B[idx];od[p+3]=255;}
    else od[p+3]=0;
  }
  tmpCtx.putImageData(out,0,0);
  return tmp;
}
function draw(){
  if(!ready)return;
  const [sx,sy]=srcXY(cur);
  ctx.clearRect(0,0,DW,DH);
  ctx.imageSmoothingEnabled=true;
  ctx.drawImage(grayC, sx,sy,cellW,cellH, 0,0,DW,DH);
  if(opacity>0){
    ctx.globalAlpha=opacity;
    ctx.imageSmoothingEnabled=false;
    ctx.drawImage(coloredCell(cur), 0,0,cellW,cellH, 0,0,DW,DH);
    ctx.globalAlpha=1; ctx.imageSmoothingEnabled=true;
  }
  $('sliceInfo').textContent=T[LANG].sliceWord+' '+(cur+1)+'/'+n+'   ·   '+ORIENT[view].axis.toUpperCase()+' = '+A().sliceMM[cur]+' mm';
  positionXhair();
  updateSliceTick();
}

/* ---- slice slider and the tick that shows the slice of the marker ---- */
function syncSlice(){
  const col=$('sliceCol'); if(!col)return;
  const h=col.clientHeight; if(h>20) $('slice').style.width=h+'px';
}
function updateSliceTick(){
  const cont=$('sliceTick'); if(!cont)return;
  cont.innerHTML='';
  const col=$('sliceCol'); if(!col){cont.style.display='none';return;}
  let list=[];
  if(marker&&marker.s!=null) list=[{s:marker.s,color:'var(--accent)'}];
  if(!list.length||n<2){ cont.style.display='none'; return; }
  const H=col.clientHeight, pad=10; cont.style.display='block';
  for(const t of list){
    const f=t.s/(n-1), y=H-(pad+f*(H-2*pad));
    const ln=document.createElement('div'); ln.className='stick';
    ln.style.top=y+'px'; ln.style.borderTopColor=t.color; ln.style.boxShadow='0 0 4px '+t.color;
    cont.appendChild(ln);
  }
}

/* ---- crosshair marker (pulsing ring + dot) ---- */
function positionXhair(){
  const el=$('xhair');
  if(!marker||!ready||(marker.s!=null&&marker.s!==cur)){el.classList.add('hidden');return;}
  const cr=cv.getBoundingClientRect(), wr=cv.parentElement.getBoundingClientRect();
  const mx=(marker.col+0.5)*K, my=(marker.row+0.5)*K;
  el.style.left=(cr.left-wr.left + mx*cr.width/DW)+'px';
  el.style.top =(cr.top -wr.top  + my*cr.height/DH)+'px';
  el.classList.remove('hidden');
}

/* ---- slice cell <-> MNI world coordinate ---- */
const FOV={ axial:{h:[90,-90],v:[90,-126]}, coronal:{h:[90,-90],v:[86,-70]}, sagittal:{h:[90,-126],v:[86,-70]} };
function cellToWorld(col,row,s,vw){
  const f=FOV[vw], o=ORIENT[vw];
  const wH=f.h[0]+(col+0.5)/cellW*(f.h[1]-f.h[0]);
  const wV=f.v[0]+(row+0.5)/cellH*(f.v[1]-f.v[0]);
  const th=o.sliceMM[s];
  if(vw==='axial')   return {x:wH, y:wV, z:th};
  if(vw==='coronal') return {x:wH, y:th, z:wV};
  return {x:th, y:wH, z:wV};
}
function worldToCell(w,vw){
  const f=FOV[vw], o=ORIENT[vw];
  let wH,wV,th;
  if(vw==='axial'){wH=w.x;wV=w.y;th=w.z;}
  else if(vw==='coronal'){wH=w.x;wV=w.z;th=w.y;}
  else {wH=w.y;wV=w.z;th=w.x;}
  let col=Math.round((wH-f.h[0])/(f.h[1]-f.h[0])*cellW-0.5);
  let row=Math.round((wV-f.v[0])/(f.v[1]-f.v[0])*cellH-0.5);
  col=Math.max(0,Math.min(cellW-1,col)); row=Math.max(0,Math.min(cellH-1,row));
  let s=0,best=1e9; for(let k=0;k<o.sliceMM.length;k++){const d=Math.abs(o.sliceMM[k]-th); if(d<best){best=d;s=k;}}
  return {col,row,s};
}

/* ---- put the marker safely inside the asked region ---- */
function onRegion(a,c,test){
  const [sx,sy]=srcXY(c.s);
  return test(labV[a][view].getImageData(sx+c.col,sy+c.row,1,1).data[0]);
}
function regionCell(a,test,w){
  const o=ORIENT[view], f=FOV[view], mm=Math.abs(f.h[1]-f.h[0])/cellW, mask=new Uint8Array(256);
  for(let i=1;i<256;i++) mask[i]=test(i)?1:0;
  const lc=labV[a][view], img=lc.getImageData(0,0,lc.canvas.width,lc.canvas.height), d=img.data, W=img.width;
  const each=(s,fn)=>{ const [sx,sy]=srcXY(s);
    for(let row=0;row<cellH;row++) for(let col=0;col<cellW;col++) if(mask[d[((sy+row)*W+sx+col)*4]]) fn(col,row); };
  const t=w?worldToCell(w,view):null;
  let best=null, bd=Infinity;
  if(t){
    for(let s=0;s<o.n;s++){ const dz=o.sliceMM[s]-o.sliceMM[t.s];
      each(s,(col,row)=>{ const x=(col-t.col)*mm, y=(row-t.row)*mm, q=x*x+y*y+dz*dz; if(q<bd){ bd=q; best={col,row,s}; } }); }
    return best;
  }
  let big=-1, bigN=0;
  for(let s=0;s<o.n;s++){ let c=0; each(s,()=>c++); if(c>bigN){ bigN=c; big=s; } }
  if(big<0) return null;

  const W2=cellW+2, D=new Uint16Array(W2*(cellH+2));
  each(big,(col,row)=>{ D[(row+1)*W2+col+1]=1; });
  for(let p=W2;p<D.length-W2;p++) if(D[p]) D[p]=Math.min(D[p-1],D[p-W2])+1;
  let deep=0;
  for(let p=D.length-W2-1;p>=W2;p--) if(D[p]){
    D[p]=Math.min(D[p],D[p+1]+1,D[p+W2]+1);
    if(D[p]>deep){ deep=D[p]; best={col:p%W2-1,row:Math.floor(p/W2)-1,s:big}; }
  }
  return best;
}
function placeQuizMarker(w){
  const isQ=j=>j===quiz.current;
  let c=w?worldToCell(w,view):A().rep[quiz.current];
  if(ready&&!(c&&onRegion(atlas,c,isQ))) c=regionCell(atlas,isQ,w)||c;
  cur=c.s; $('slice').value=cur;
  marker={col:c.col,row:c.row,s:c.s,w:cellToWorld(c.col,c.row,c.s,view)};
}

/* ---- scroll through slices: slider, mouse wheel, vertical swipe ---- */
$('slice').addEventListener('input',e=>{cur=+e.target.value;draw();});
document.querySelector('.canvas-wrap').addEventListener('wheel',e=>{
  e.preventDefault();
  const step = e.deltaY<0 ? 1 : -1;
  const nc = Math.max(0, Math.min(n-1, cur+step));
  if(nc===cur) return;
  cur=nc; $('slice').value=cur; draw();
},{passive:false});
(function(){
  const wrap=document.querySelector('.canvas-wrap'); let y0=0,c0=0,active=false;
  wrap.addEventListener('touchstart',e=>{ if(e.touches.length!==1)return; y0=e.touches[0].clientY; c0=cur; active=true; swiped=false; },{passive:true});
  wrap.addEventListener('touchmove',e=>{
    if(!active||e.touches.length!==1)return;
    const dy=y0-e.touches[0].clientY;
    if(Math.abs(dy)>8){ swiped=true; e.preventDefault(); }
    const nc=Math.max(0,Math.min(n-1,c0+Math.round(dy/16)));
    if(nc!==cur){ cur=nc; $('slice').value=cur; draw(); }
  },{passive:false});
  wrap.addEventListener('touchend',()=>{active=false;},{passive:true});
})();

/* ---- phone / laptop layout switch ---- */
function setDevice(){document.body.classList.toggle('mobile', (window.matchMedia&&matchMedia('(pointer:coarse)').matches) || innerWidth<=860);}
setDevice();
addEventListener('resize',()=>{setDevice();syncSlice();positionXhair();updateSliceTick();});
addEventListener('orientationchange',()=>{setDevice();setTimeout(()=>{syncSlice();positionXhair();updateSliceTick();},200);});
